                    join.params.W = std::fmin(dyn.W[0], dyn.W[1]);
                    join.params.alpha = join.params.W * dyn.k;
                    join.params.v_max = dyn.v_max;
                    join.params.a_lin = dyn.a_lin;
                    join.params.r_gate = gate_geo.r;
